const ADMIN_HTML = "\n<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta name=\"theme-color\" content=\"#0d9488\">\n<title>Dashboard Admin | SIAP GURU</title>\n\n<style>\n:root{\n  --primary:#0d9488;\n  --primary-dark:#0f766e;\n  --orange:#f97316;\n  --bg:#f5f8fa;\n  --white:#ffffff;\n  --text:#1e293b;\n  --muted:#64748b;\n  --border:#e5edf0;\n  --sidebar:260px;\n}\n*{box-sizing:border-box}\nbody{\n  margin:0;\n  font-family:Inter,Arial,sans-serif;\n  background:var(--bg);\n  color:var(--text);\n}\nbutton{font:inherit;cursor:pointer}\n.layout{display:flex;min-height:100vh}\n\n/* SIDEBAR */\n.sidebar{\n  width:var(--sidebar);\n  background:#fff;\n  border-right:1px solid var(--border);\n  padding:25px 17px;\n  position:fixed;\n  inset:0 auto 0 0;\n  z-index:10;\n  display:flex;\n  flex-direction:column;\n}\n.brand{\n  display:flex;\n  align-items:center;\n  gap:12px;\n  padding:0 10px 28px;\n}\n.brand-icon{\n  width:43px;height:43px;\n  border-radius:13px;\n  display:grid;place-items:center;\n  color:white;font-weight:800;\n  font-size:19px;\n  background:linear-gradient(135deg,var(--primary),var(--primary-dark));\n}\n.brand h2{font-size:18px;margin:0}\n.brand small{color:var(--muted);font-size:11px}\n.menu-label{\n  font-size:10px;\n  font-weight:700;\n  color:#94a3b8;\n  letter-spacing:1.3px;\n  padding:17px 12px 9px;\n}\n.nav-item{\n  width:100%;\n  border:0;\n  background:transparent;\n  color:#64748b;\n  padding:12px 13px;\n  border-radius:10px;\n  text-align:left;\n  display:flex;\n  align-items:center;\n  gap:12px;\n  font-size:13px;\n  margin:2px 0;\n  transition:.2s;\n}\n.nav-item:hover,.nav-item.active{\n  color:var(--primary-dark);\n  background:#e9f8f6;\n  font-weight:700;\n}\n.nav-icon{font-size:17px;width:22px;text-align:center}\n.sidebar-bottom{\n  margin-top:auto;\n  border-top:1px solid var(--border);\n  padding-top:17px;\n}\n.admin-profile{\n  display:flex;align-items:center;gap:10px;\n  padding:10px;\n}\n.avatar{\n  width:37px;height:37px;border-radius:50%;\n  display:grid;place-items:center;\n  background:#ffedd5;color:#c2410c;font-weight:800;\n}\n.admin-profile strong{font-size:12px}\n.admin-profile small{display:block;color:var(--muted);font-size:11px;margin-top:3px}\n\n/* MAIN */\n.main{\n  margin-left:var(--sidebar);\n  width:calc(100% - var(--sidebar));\n  min-width:0;\n}\n.topbar{\n  height:75px;\n  background:#fff;\n  border-bottom:1px solid var(--border);\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  padding:0 32px;\n  position:sticky;top:0;z-index:5;\n}\n.topbar h2{font-size:17px;margin:0}\n.topbar small{color:var(--muted);font-size:11px}\n.top-actions{display:flex;align-items:center;gap:12px}\n.status{\n  background:#e9f8f6;\n  color:var(--primary-dark);\n  padding:8px 12px;\n  border-radius:30px;\n  font-size:11px;font-weight:700;\n}\n.content{padding:30px;max-width:1500px;margin:auto}\n.welcome{\n  display:flex;justify-content:space-between;\n  align-items:center;gap:15px;flex-wrap:wrap;\n  margin-bottom:25px;\n}\n.welcome h1{font-size:24px;margin:0 0 7px}\n.welcome p{margin:0;color:var(--muted);font-size:13px}\n.date-box{\n  background:#fff;border:1px solid var(--border);\n  padding:12px 16px;border-radius:12px;\n  font-size:12px;color:var(--muted);\n}\n\n/* CARDS */\n.stats{\n  display:grid;\n  grid-template-columns:repeat(4,minmax(0,1fr));\n  gap:17px;\n}\n.stat-card{\n  background:#fff;border:1px solid var(--border);\n  border-radius:15px;padding:20px;\n  min-width:0;\n}\n.stat-head{\n  display:flex;justify-content:space-between;\n  align-items:center;margin-bottom:18px;\n}\n.stat-icon{\n  width:40px;height:40px;border-radius:12px;\n  display:grid;place-items:center;font-size:19px;\n}\n.teal{background:#e0f7f4;color:#0d9488}\n.orange{background:#fff0e5;color:#ea580c}\n.blue{background:#eaf2ff;color:#2563eb}\n.purple{background:#f2eafe;color:#9333ea}\n.stat-card p{font-size:12px;color:var(--muted);margin:0 0 9px}\n.stat-card h2{font-size:25px;margin:0;font-weight:750}\n.stat-card small{font-size:10px;color:#94a3b8}\n\n/* SECTIONS */\n.section-grid{\n  display:grid;\n  grid-template-columns:1.4fr 1fr;\n  gap:18px;margin-top:22px;\n}\n.panel{\n  background:#fff;border:1px solid var(--border);\n  border-radius:15px;padding:21px;\n  min-width:0;\n}\n.panel-header{\n  display:flex;justify-content:space-between;\n  align-items:center;gap:10px;margin-bottom:18px;\n}\n.panel-header h3{font-size:14px;margin:0}\n.panel-header small{font-size:11px;color:var(--muted)}\n.empty{\n  min-height:175px;\n  display:flex;flex-direction:column;\n  align-items:center;justify-content:center;\n  text-align:center;color:var(--muted);\n  font-size:12px;gap:10px;\n}\n.empty-icon{font-size:32px;opacity:.65}\n.quick-grid{\n  display:grid;grid-template-columns:1fr 1fr;\n  gap:11px;\n}\n.quick{\n  background:#f8fafc;border:1px solid var(--border);\n  border-radius:12px;padding:15px;\n  text-align:left;color:var(--text);\n}\n.quick:hover{border-color:var(--primary);background:#f0fdfa}\n.quick span{font-size:21px}\n.quick strong{display:block;font-size:12px;margin-top:9px}\n.quick small{font-size:10px;color:var(--muted)}\n.table-wrap{overflow-x:auto}\ntable{border-collapse:collapse;width:100%;font-size:12px}\nth{\n  text-align:left;color:var(--muted);\n  background:#f8fafc;font-weight:600;\n  padding:12px;\n}\ntd{padding:13px 12px;border-bottom:1px solid var(--border)}\n.footer{\n  text-align:center;color:#94a3b8;\n  font-size:10px;padding:30px 10px;\n}\n.page{display:none}\n.page.active{display:block}\n.mobile-toggle{display:none}\n\n/* RESPONSIVE */\n@media(max-width:1050px){\n  .stats{grid-template-columns:repeat(2,1fr)}\n  .section-grid{grid-template-columns:1fr}\n}\n@media(max-width:700px){\n  .sidebar{\n    transform:translateX(-100%);\n    transition:.25s;\n    box-shadow:5px 0 25px #0001;\n  }\n  .sidebar.open{transform:translateX(0)}\n  .main{margin-left:0;width:100%}\n  .topbar{padding:0 16px;height:65px}\n  .mobile-toggle{display:block;border:0;background:#e9f8f6;padding:9px 12px;border-radius:9px}\n  .content{padding:20px 15px}\n  .welcome h1{font-size:20px}\n  .stats{gap:10px}\n  .stat-card{padding:14px}\n  .stat-card h2{font-size:21px}\n  .stat-card p{font-size:11px}\n  .date-box{width:100%}\n}\n\n.btn-primary,.btn-danger{border:0;border-radius:8px;padding:9px 13px;font-size:12px;font-weight:700;cursor:pointer}\n.btn-primary{background:#0d9488;color:#fff}.btn-primary:hover{background:#0f766e}\n.btn-danger{background:#fee2e2;color:#b91c1c}.btn-danger:hover{background:#fecaca}\n.settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}\n@media(max-width:700px){.settings-grid{grid-template-columns:1fr}}\n\n\n.print-only{display:none}\n@media print{\n  @page{size:A4;margin:14mm}\n  body.print-analysis{background:#fff!important}\n  body.print-analysis .sidebar,\n  body.print-analysis .topbar,\n  body.print-analysis .footer,\n  body.print-analysis #analysisTools,\n  body.print-analysis #dashboard>*:not(#dashAnalysis){display:none!important}\n  body.print-analysis .main{margin-left:0!important;width:100%!important}\n  body.print-analysis .content{padding:0!important;max-width:none!important}\n  body.print-analysis #dashAnalysis{margin:0!important;border:0!important;box-shadow:none!important;padding:0!important}\n  body.print-analysis .print-only{display:block}\n  body.print-analysis *{-webkit-print-color-adjust:exact;print-color-adjust:exact}\n  body.print-analysis tr{page-break-inside:avoid}\n}\n</style>\n</head>\n\n<body>\n<div class=\"layout\">\n\n<aside class=\"sidebar\" id=\"sidebar\">\n  <div class=\"brand\">\n    <div class=\"brand-icon\">SG</div>\n    <div>\n      <h2>SIAP GURU</h2>\n      <small>Nama Sekolah</small>\n    </div>\n  </div>\n\n  <div class=\"menu-label\">MENU UTAMA</div>\n  <button class=\"nav-item active\" data-page=\"dashboard\">\n    <span class=\"nav-icon\">▦</span> Dashboard\n  </button>\n  <button class=\"nav-item\" data-page=\"guru\">\n    <span class=\"nav-icon\">♙</span> Data Guru\n  </button>\n  <button class=\"nav-item\" data-page=\"pendaftaran\">\n    <span class=\"nav-icon\">☷</span> Persetujuan Guru\n  </button>\n\n  <div class=\"menu-label\">PRESENSI</div>\n  <button class=\"nav-item\" data-page=\"monitoring\">\n    <span class=\"nav-icon\">◷</span> Monitoring Presensi\n  </button>\n  <button class=\"nav-item\" data-page=\"laporan\">\n    <span class=\"nav-icon\">▤</span> Laporan Presensi\n  </button>\n\n  <div class=\"menu-label\">LAYANAN GURU</div>\n  <button class=\"nav-item\" data-page=\"izin\">\n    <span class=\"nav-icon\">✎</span> Izin & Cuti\n  </button>\n\n  <div class=\"menu-label\">PENGATURAN</div>\n  <button class=\"nav-item\" data-page=\"pengaturan\">\n    <span class=\"nav-icon\">⚙</span> Pengaturan Sistem\n  </button>\n\n  <div class=\"sidebar-bottom\">\n    <div class=\"admin-profile\">\n      <div class=\"avatar\">A</div>\n      <div>\n        <strong>Administrator</strong>\n        <small>Administrator</small>\n      </div>\n    </div>\n  </div>\n</aside>\n\n<main class=\"main\">\n  <header class=\"topbar\">\n    <div style=\"display:flex;align-items:center;gap:12px\">\n      <button class=\"mobile-toggle\" id=\"toggleMenu\">☰</button>\n      <div>\n        <h2 id=\"topTitle\">Dashboard</h2>\n        <small>Panel Administrator SIAP GURU</small>\n      </div>\n    </div>\n    <div class=\"top-actions\">\n      <span class=\"status\">● Antarmuka awal</span>\n    </div>\n  </header>\n\n  <div class=\"content\">\n\n    <section class=\"page active\" id=\"dashboard\">\n      <div class=\"welcome\">\n        <div>\n          <h1>Selamat Datang, Administrator! 👋</h1>\n          <p>Ringkasan pengelolaan presensi guru Nama Sekolah.</p>\n        </div>\n        <div class=\"date-box\" id=\"today\">Memuat tanggal...</div>\n      </div>\n\n      <div class=\"stats\">\n        <div class=\"stat-card\">\n          <div class=\"stat-head\">\n            <div class=\"stat-icon teal\">♙</div>\n            <small>DATA GURU</small>\n          </div>\n          <p>Total Guru Terdaftar</p>\n          <h2>—</h2>\n          <small>Menunggu koneksi database</small>\n        </div>\n\n        <div class=\"stat-card\">\n          <div class=\"stat-head\">\n            <div class=\"stat-icon orange\">📍</div>\n            <small>DATANG</small>\n          </div>\n          <p>Presensi Kedatangan</p>\n          <h2>—</h2>\n          <small>Data belum tersedia</small>\n        </div>\n\n        <div class=\"stat-card\">\n          <div class=\"stat-head\">\n            <div class=\"stat-icon blue\">🏁</div>\n            <small>PULANG</small>\n          </div>\n          <p>Presensi Kepulangan</p>\n          <h2>—</h2>\n          <small>Data belum tersedia</small>\n        </div>\n\n        <div class=\"stat-card\">\n          <div class=\"stat-head\">\n            <div class=\"stat-icon purple\">☷</div>\n            <small>PENDAFTARAN</small>\n          </div>\n          <p>Menunggu Persetujuan</p>\n          <h2>—</h2>\n          <small>Data belum tersedia</small>\n        </div>\n      </div>\n\n      <div class=\"section-grid\">\n        <div class=\"panel\">\n          <div class=\"panel-header\">\n            <h3>Monitoring Presensi Hari Ini</h3>\n            <small>DATANG & PULANG</small>\n          </div>\n          <div class=\"empty\">\n            <div class=\"empty-icon\">📊</div>\n            <strong>Belum terhubung dengan database</strong>\n            <span>Data presensi akan tampil setelah integrasi API selesai.</span>\n          </div>\n        </div>\n\n        <div class=\"panel\">\n          <div class=\"panel-header\">\n            <h3>Akses Cepat</h3>\n            <small>MENU ADMIN</small>\n          </div>\n          <div class=\"quick-grid\">\n            <button class=\"quick\" data-target=\"guru\">\n              <span>♙</span>\n              <strong>Data Guru</strong>\n              <small>Kelola pengguna</small>\n            </button>\n            <button class=\"quick\" data-target=\"pendaftaran\">\n              <span>☷</span>\n              <strong>Pendaftaran</strong>\n              <small>Persetujuan guru</small>\n            </button>\n            <button class=\"quick\" data-target=\"monitoring\">\n              <span>◷</span>\n              <strong>Presensi</strong>\n              <small>Monitoring harian</small>\n            </button>\n            <button class=\"quick\" data-target=\"laporan\">\n              <span>▤</span>\n              <strong>Laporan</strong>\n              <small>Rekap presensi</small>\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"panel\" id=\"dashAnalysis\" style=\"margin-top:20px\">\n        <div class=\"panel-header\">\n          <h3>Rekap &amp; Analisis Presensi</h3>\n          <div id=\"analysisTools\" style=\"display:flex;gap:8px;align-items:center;flex-wrap:wrap\">\n            <select id=\"analysisRange\" style=\"padding:8px 10px;border:1px solid #dbe3e8;border-radius:9px;font-size:12px\">\n              <option value=\"7\">7 hari terakhir</option>\n              <option value=\"30\">30 hari terakhir</option>\n              <option value=\"month\">Bulan ini</option>\n            </select>\n            <button class=\"btn-primary\" id=\"printAnalysis\" type=\"button\">Cetak / Simpan PDF</button>\n          </div>\n        </div>\n        <div class=\"print-only\" id=\"printHeader\"></div>\n        <div id=\"analysisBody\" style=\"font-size:13px;color:#64748b\">Memuat analisis...</div>\n      </div>\n\n      <div id=\"dashActivity\" style=\"margin-top:20px\">\n        <div class=\"panel\">\n          <div class=\"panel-header\">\n            <h3>Aktivitas Terbaru</h3>\n            <small>LOG SISTEM</small>\n          </div>\n          <div class=\"empty\" style=\"min-height:110px\">\n            <div class=\"empty-icon\">🔔</div>\n            <strong>Belum ada aktivitas untuk ditampilkan</strong>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"page\" id=\"guru\">\n      <div class=\"welcome\">\n        <div>\n          <h1>Data Guru</h1>\n          <p>Pengelolaan data pengguna SIAP GURU.</p>\n        </div>\n      </div>\n      <div class=\"panel\">\n        <div class=\"panel-header\">\n          <h3>Daftar Guru</h3>\n          <small>DATABASE BELUM TERHUBUNG</small>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead><tr>\n              <th>No.</th><th>Nama Guru</th><th>NIP</th>\n              <th>Status Kepegawaian</th><th>Status Akun</th>\n            </tr></thead>\n            <tbody><tr><td colspan=\"5\" style=\"text-align:center;padding:35px;color:#64748b\">\n              Data guru akan ditampilkan setelah integrasi API.\n            </td></tr></tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"page\" id=\"pendaftaran\">\n      <div class=\"welcome\">\n        <div>\n          <h1>Persetujuan Guru</h1>\n          <p>Verifikasi pendaftaran akun guru baru.</p>\n        </div>\n      </div>\n      <div class=\"panel\">\n        <div class=\"empty\">\n          <div class=\"empty-icon\">☷</div>\n          <strong>Belum terhubung dengan database</strong>\n          <span>Daftar pendaftaran yang berstatus PENDING akan tampil di sini.</span>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"page\" id=\"monitoring\">\n      <div class=\"welcome\">\n        <div>\n          <h1>Monitoring Presensi</h1>\n          <p>Pemantauan kejadian DATANG dan PULANG guru.</p>\n        </div>\n      </div>\n      <div class=\"panel\">\n        <div class=\"panel-header\">\n          <h3>Presensi Harian</h3>\n          <small>DATANG & PULANG</small>\n        </div>\n        <div class=\"empty\">\n          <div class=\"empty-icon\">◷</div>\n          <strong>Data presensi belum tersedia</strong>\n          <span>Informasi akan diambil langsung dari database D1.</span>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"page\" id=\"laporan\">\n      <div class=\"welcome\">\n        <div>\n          <h1>Laporan Presensi</h1>\n          <p>Rekapitulasi presensi guru berdasarkan periode.</p>\n        </div>\n      </div>\n      <div class=\"panel\">\n        <div class=\"empty\">\n          <div class=\"empty-icon\">▤</div>\n          <strong>Modul laporan belum diaktifkan</strong>\n          <span>Fitur rekap dan unduh laporan akan dibuat pada tahap berikutnya.</span>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"page\" id=\"izin\">\n      <div class=\"welcome\">\n        <div>\n          <h1>Izin & Cuti</h1>\n          <p>Pengelolaan permohonan izin dan cuti guru.</p>\n        </div>\n      </div>\n      <div class=\"panel\">\n        <div class=\"empty\">\n          <div class=\"empty-icon\">✎</div>\n          <strong>Belum ada data permohonan</strong>\n          <span>Data akan muncul setelah modul izin dan cuti terintegrasi.</span>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"page\" id=\"pengaturan\">\n      <div class=\"welcome\">\n        <div>\n          <h1>Pengaturan Sistem</h1>\n          <p>Konfigurasi dasar presensi Nama Sekolah.</p>\n        </div>\n      </div>\n      <div class=\"panel\">\n        <h3 style=\"font-size:14px\">Informasi Sekolah</h3>\n        <p style=\"font-size:13px;color:#64748b\">Memuat pengaturan sekolah...</p>\n        <p style=\"font-size:11px;color:#94a3b8\">\n          Pengaturan ini masih bersifat informasi tampilan. Perubahan konfigurasi akan diaktifkan melalui API.\n        </p>\n      </div>\n    </section>\n\n  </div>\n\n  <footer class=\"footer\">\n    © 2026 SIAP GURU · Nama Sekolah · Sistem Informasi Absensi dan Presensi Guru\n  </footer>\n</main>\n</div>\n\n<script>\n\n// ======================================================\n// KONFIGURASI SEKOLAH (satu-satunya baris yang WAJIB diubah)\n// Ganti nilai di bawah dengan alamat Worker backend sekolah Anda.\n// Contoh : \"https://siap-guru-namasekolah.akun-anda.workers.dev\"\n// Aturan : diawali https://, tanpa garis miring (/) di akhir.\n// ======================================================\nconst API_BASE = \"__ISI_URL_WORKER__\";\nif (!/^https:\\/\\/[^\\s/]+$/.test(API_BASE)) {\n  document.documentElement.style.visibility = \"visible\";\n  (document.body || document.documentElement).innerHTML =\n    '<div style=\"font-family:system-ui,sans-serif;max-width:520px;margin:12vh auto;padding:24px;border:1px solid #fecaca;background:#fef2f2;border-radius:12px;color:#7f1d1d\">' +\n    '<h2 style=\"margin:0 0 8px\">Konfigurasi belum lengkap</h2>' +\n    '<p style=\"margin:0;line-height:1.5\">Nilai <b>API_BASE</b> di file admin.html belum diisi dengan benar. ' +\n    'Isi dengan alamat Worker backend (diawali https://, tanpa garis miring di akhir), lalu unggah ulang file ini.</p></div>';\n  throw new Error(\"API_BASE belum diisi\");\n}\nconst titles = {\n  dashboard:\"Dashboard\", guru:\"Data Guru\", pendaftaran:\"Persetujuan Guru\",\n  monitoring:\"Monitoring Presensi\", laporan:\"Laporan Presensi\",\n  izin:\"Izin & Cuti\", pengaturan:\"Pengaturan Sistem\"\n};\ndocument.documentElement.style.visibility = \"hidden\";\nlet adminUser = null;\nlet currentSettings = null;\nfunction applySchoolIdentity(name){\n  const schoolName=String(name||\"Nama Sekolah\").trim()||\"Nama Sekolah\";\n  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);\n  let node;\n  while((node=walker.nextNode())){\n    if(node.nodeValue.includes(\"Nama Sekolah\")) node.nodeValue=node.nodeValue.replaceAll(\"Nama Sekolah\",schoolName);\n  }\n  document.title=`Dashboard Admin | SIAP GURU ${schoolName}`;\n}\n\nconst $ = (s, root=document) => root.querySelector(s);\nconst esc = v => String(v ?? \"\").replace(/[&<>\"']/g, c => ({\n  \"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"\n}[c]));\nlet schoolTimezone = \"Asia/Makassar\";\nconst todaySchoolDate = () => new Intl.DateTimeFormat(\"en-CA\", {\n  timeZone:schoolTimezone, year:\"numeric\", month:\"2-digit\", day:\"2-digit\"\n}).format(new Date());\nconst fmtDate = v => {\n  if (!v) return \"-\";\n  const [year, month, day] = String(v).split(\"-\").map(Number);\n  const date = new Date(Date.UTC(year, month - 1, day, 12));\n  return new Intl.DateTimeFormat(\"id-ID\", {\n    timeZone:schoolTimezone, day:\"2-digit\", month:\"long\", year:\"numeric\"\n  }).format(date);\n};\nconst fmtTime = v => v ? String(v).slice(0,5) : \"-\";\nconst statusPill = s => {\n  const bad = /TIDAK|REJECT|TERLAMBAT|CEPAT|PENDING|BELUM/i.test(s);\n  const good = /HADIR|APPROVED|DISETUJUI/i.test(s);\n  const bg = good ? \"#dcfce7\" : bad ? \"#ffedd5\" : \"#e2e8f0\";\n  const color = good ? \"#166534\" : bad ? \"#9a3412\" : \"#475569\";\n  return `<span style=\"display:inline-block;padding:5px 9px;border-radius:20px;background:${bg};color:${color};font-size:11px;font-weight:700\">${esc(s||\"-\")}</span>`;\n};\nfunction token(){ return sessionStorage.getItem(\"siapGuruSession\"); }\nasync function api(path, options={}) {\n  const headers = { \"Authorization\":\"Bearer \"+token(), ...(options.body?{\"Content-Type\":\"application/json\"}:{}), ...(options.headers||{}) };\n  const res = await fetch(API_BASE+path, {...options, headers});\n  let data={}; try { data=await res.json(); } catch {}\n  if (res.status===401) {\n    sessionStorage.removeItem(\"siapGuruSession\");\n    createLoginScreen(\"Sesi berakhir. Silakan login kembali.\");\n    throw new Error(\"Sesi admin berakhir.\");\n  }\n  if (!res.ok || data.success===false) throw new Error(data.error || data.message || `Permintaan gagal (${res.status})`);\n  return data;\n}\nfunction createLoginScreen(message=\"\") {\n  $(\".layout\").style.display=\"none\";\n  let screen=$(\"#authScreen\");\n  if(!screen){\n    screen=document.createElement(\"div\"); screen.id=\"authScreen\";\n    screen.style.cssText=\"min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f5f8fa;padding:20px;font-family:Inter,Arial,sans-serif\";\n    screen.innerHTML=`<div style=\"width:100%;max-width:410px;background:white;padding:35px;border-radius:20px;text-align:center;box-shadow:0 10px 40px #0f172a12\">\n      <div style=\"width:65px;height:65px;margin:0 auto 18px;border-radius:18px;background:#0d9488;color:white;display:grid;place-items:center;font-size:25px;font-weight:800\">SG</div>\n      <h2 style=\"margin:0;color:#1e293b\">SIAP GURU</h2><p style=\"color:#64748b;font-size:13px\">Panel Administrator Nama Sekolah</p>\n      <p id=\"authMessage\" style=\"color:#dc2626;font-size:12px;margin:18px 0\"></p>\n      <button id=\"telegramLogin\" style=\"width:100%;padding:14px;border:0;border-radius:10px;background:#0d9488;color:white;font-weight:700;font-size:14px;cursor:pointer\">Login dengan Telegram</button>\n      <p style=\"color:#94a3b8;font-size:11px;margin-top:20px\">Akses khusus administrator sekolah</p></div>`;\n    document.body.appendChild(screen);\n    $(\"#telegramLogin\").onclick=()=>location.href=API_BASE+\"/auth/login?frontend=\"+encodeURIComponent(location.origin);\n  }\n  $(\"#authMessage\").textContent=message;\n  document.documentElement.style.visibility=\"visible\";\n}\nasync function verifyAdminSession(){\n  const params=new URLSearchParams(location.hash.slice(1)), newToken=params.get(\"session\");\n  if(newToken){sessionStorage.setItem(\"siapGuruSession\",newToken);history.replaceState(null,document.title,location.pathname+location.search);}\n  if(!token()){createLoginScreen(new URLSearchParams(location.search).get(\"auth_error\")||\"Silakan login untuk melanjutkan.\");return;}\n  try{\n    const r=await fetch(API_BASE+\"/auth/me\",{headers:{\"Authorization\":\"Bearer \"+token()}});\n    if(!r.ok) throw new Error(\"Sesi tidak valid atau sudah berakhir.\");\n    const result=await r.json();\n    if(!result.authenticated||!result.user) throw new Error(\"Akses administrator ditolak.\");\n    adminUser=result.user;\n    const schoolResult = await api(\"/admin/settings\");\n    currentSettings = schoolResult.data || null;\n    schoolTimezone = currentSettings?.timezone || \"Asia/Makassar\";\n    if (currentSettings?.school_name) applySchoolIdentity(currentSettings.school_name);\n    $(\".layout\").style.display=\"flex\";\n    const name=adminUser.name||\"Administrator\";\n    $(\".welcome h1\").textContent=\"Selamat Datang, \"+name+\"! 👋\";\n    $(\".admin-profile strong\").textContent=name;\n    $(\".admin-profile .avatar\").textContent=name.charAt(0).toUpperCase();\n    $(\".status\").textContent=\"● Terhubung\";\n    $(\".status\").style.background=\"#dcfce7\"; $(\".status\").style.color=\"#166534\";\n    addLogoutButton(); document.documentElement.style.visibility=\"visible\";\n    await loadDashboard();\n  }catch(e){sessionStorage.removeItem(\"siapGuruSession\");createLoginScreen(e.message);}\n}\nfunction addLogoutButton(){\n  if($(\"#logoutButton\")) return;\n  const b=document.createElement(\"button\"); b.id=\"logoutButton\"; b.textContent=\"Keluar\";\n  b.style.cssText=\"border:0;border-radius:9px;padding:9px 14px;background:#fff0e5;color:#c2410c;font-weight:700;cursor:pointer\";\n  b.onclick=async()=>{try{await fetch(API_BASE+\"/auth/logout\",{method:\"POST\",headers:{\"Authorization\":\"Bearer \"+token()}});}catch(e){console.warn(e);}\n    sessionStorage.removeItem(\"siapGuruSession\");location.reload();};\n  $(\".top-actions\").appendChild(b);\n}\nfunction showPage(page){\n  document.querySelectorAll(\".page\").forEach(el=>el.classList.toggle(\"active\",el.id===page));\n  document.querySelectorAll(\".nav-item\").forEach(el=>el.classList.toggle(\"active\",el.dataset.page===page));\n  $(\"#topTitle\").textContent=titles[page]||\"Dashboard\"; $(\"#sidebar\").classList.remove(\"open\");\n  const loaders={dashboard:loadDashboard,guru:loadTeachers,pendaftaran:loadPending,monitoring:loadMonitoring,laporan:loadReports,izin:loadLeaves,pengaturan:loadSettings};\n  if(loaders[page]) loaders[page]().catch(showError);\n}\nfunction showError(e){\n  console.error(e);\n  const active=$(\".page.active\");\n  if(active){\n    let box=active.querySelector(\".api-error\");\n    if(!box){box=document.createElement(\"div\");box.className=\"api-error\";box.style.cssText=\"margin:12px 0;padding:12px 14px;border-radius:10px;background:#fff1f2;color:#be123c;font-size:12px\";active.prepend(box);}\n    box.textContent=\"Gagal memuat data: \"+(e.message||\"Terjadi kesalahan.\");\n  } else alert(e.message||\"Terjadi kesalahan.\");\n}\nfunction panel(title, subtitle, body){return `<div class=\"panel\"><div class=\"panel-header\"><h3>${title}</h3><small>${subtitle||\"\"}</small></div>${body}</div>`;}\nfunction table(headers, rows, empty=\"Belum ada data.\") {\n  return `<div class=\"table-wrap\"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join(\"\")}</tr></thead><tbody>${rows||`<tr><td colspan=\"${headers.length}\" style=\"text-align:center;padding:28px;color:#64748b\">${empty}</td></tr>`}</tbody></table></div>`;\n}\nfunction setPage(id, html){$(\"#\"+id).innerHTML=html;}\nfunction setWelcome(id,title,desc,extra=\"\"){setPage(id,`<div class=\"welcome\"><div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`+($(\"#\"+id).dataset.content||\"\"));}\nfunction dateInput(id,value){return `<input id=\"${id}\" type=\"date\" value=\"${esc(value)}\" style=\"padding:10px;border:1px solid #dbe3e8;border-radius:9px\">`;}\nasync function loadDashboard(){\n  $(\"#today\").textContent=new Date().toLocaleDateString(\"id-ID\",{weekday:\"long\",day:\"numeric\",month:\"long\",year:\"numeric\",timeZone:schoolTimezone});\n  const date=todaySchoolDate();\n  const [teachers,monitor,pending,leaves]=await Promise.all([\n    api(\"/admin/teachers?status=ALL\"),api(\"/admin/attendance/monitoring?date=\"+date),\n    api(\"/admin/teachers?status=PENDING\"),api(\"/admin/leave-requests?status=PENDING\")\n  ]);\n  const cards=[[\"Total Guru\",teachers.total||0,\"♙\",\"teal\"],[\"Hadir Datang\",monitor.total_hadir||0,\"📍\",\"orange\"],[\"Belum Absen Datang\",monitor.total_belum_datang||0,\"◷\",\"blue\"],[\"Menunggu Persetujuan\",(pending.total||0)+(leaves.total||0),\"☷\",\"purple\"]];\n  $(\".stats\").innerHTML=cards.map(c=>`<div class=\"stat-card\"><div class=\"stat-head\"><div class=\"stat-icon ${c[3]}\">${c[2]}</div><small>SIAP GURU</small></div><p>${c[0]}</p><h2>${c[1]}</h2><small>Data terkini dari database</small></div>`).join(\"\");\n  const rows=(monitor.data||[]).slice(0,8).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.teacher_name)}</td><td>${statusPill(x.status_datang)}</td><td>${fmtTime(x.waktu_datang)}</td><td>${statusPill(x.status_pulang)}</td><td>${fmtTime(x.waktu_pulang)}</td></tr>`).join(\"\");\n  $(\".section-grid\").innerHTML=panel(\"Monitoring Presensi Hari Ini\",fmtDate(date),table([\"No\",\"Nama Guru\",\"Datang\",\"Waktu\",\"Pulang\",\"Waktu\"],rows,\"Belum ada data guru atau presensi.\"))+panel(\"Akses Cepat\",\"MENU ADMIN\",`<div class=\"quick-grid\"><button class=\"quick\" data-target=\"guru\"><span>♙</span><strong>Data Guru</strong><small>Kelola pengguna</small></button><button class=\"quick\" data-target=\"pendaftaran\"><span>☷</span><strong>Pendaftaran</strong><small>Persetujuan guru</small></button><button class=\"quick\" data-target=\"monitoring\"><span>◷</span><strong>Presensi</strong><small>Monitoring harian</small></button><button class=\"quick\" data-target=\"laporan\"><span>▤</span><strong>Laporan</strong><small>Rekap presensi</small></button></div>`);\n  $(\".quick\").parentElement.querySelectorAll(\"[data-target]\").forEach(b=>b.onclick=()=>showPage(b.dataset.target));\n  $(\"#dashActivity\").innerHTML=panel(\"Ringkasan Layanan\",\"PENDING\",`<p style=\"font-size:13px;color:#64748b\">Pendaftaran guru menunggu: <b>${pending.total||0}</b> · Pengajuan izin menunggu: <b>${leaves.total||0}</b> · Belum absen pulang: <b>${monitor.total_belum_pulang||0}</b></p>`);\n  loadAnalysis().catch(err=>{const b=$(\"#analysisBody\");if(b)b.textContent=err.message||\"Gagal memuat analisis.\";});\n}\nasync function loadTeachers(){\n  setPage(\"guru\",`<div class=\"welcome\"><div><h1>Data Guru</h1><p>Data guru yang terdaftar pada sistem.</p></div><button class=\"btn-primary\" id=\"refreshTeachers\">Muat Ulang</button></div>\n    <div class=\"panel\"><div class=\"panel-header\"><h3>Daftar Guru</h3><small id=\"teacherCount\">Memuat...</small></div><div id=\"teacherTable\"></div></div>`);\n  $(\"#refreshTeachers\").onclick=loadTeachers;\n  const r=await api(\"/admin/teachers?status=ALL\");\n  $(\"#teacherCount\").textContent=`${r.total||0} akun`;\n  const rows=(r.data||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.full_name)}</td><td>${esc(x.employment_status===\"NON_ASN\"?\"NON ASN\":x.employment_status||\"—\")}</td><td>${esc(x.nip||\"—\")}</td><td>${esc(x.position||\"—\")}</td><td>${statusPill(x.approval_status)}</td></tr>`).join(\"\");\n  $(\"#teacherTable\").innerHTML=table([\"No\",\"NAMA\",\"STATUS\",\"NIP\",\"JABATAN\",\"Status Akun\"],rows,\"Belum ada guru terdaftar.\");\n}\nasync function loadPending(){\n  setPage(\"pendaftaran\",`<div class=\"welcome\"><div><h1>Persetujuan Guru</h1><p>Verifikasi pendaftaran akun guru baru.</p></div><button class=\"btn-primary\" id=\"refreshPending\">Muat Ulang</button></div><div class=\"panel\"><div class=\"panel-header\"><h3>Pendaftaran Menunggu</h3><small id=\"pendingCount\"></small></div><div id=\"pendingTable\"></div></div>`);\n  $(\"#refreshPending\").onclick=loadPending;\n  const r=await api(\"/admin/teachers?status=PENDING\"); $(\"#pendingCount\").textContent=`${r.total||0} pendaftaran`;\n  const rows=(r.data||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.full_name)}</td><td>${esc(x.employment_status===\"NON_ASN\"?\"NON ASN\":x.employment_status||\"—\")}</td><td>${esc(x.nip||\"—\")}</td><td>${esc(x.position||\"—\")}</td><td>${statusPill(x.approval_status)}</td><td><button class=\"btn-primary\" data-approve=\"${x.id}\">Setujui</button> <button class=\"btn-danger\" data-reject=\"${x.id}\">Tolak</button></td></tr>`).join(\"\");\n  $(\"#pendingTable\").innerHTML=table([\"No\",\"NAMA\",\"STATUS\",\"NIP\",\"JABATAN\",\"Status\",\"Tindakan\"],rows,\"Tidak ada pendaftaran yang menunggu.\");\n  $(\"#pendingTable\").querySelectorAll(\"[data-approve]\").forEach(b=>b.onclick=()=>reviewTeacher(b.dataset.approve,\"APPROVE\"));\n  $(\"#pendingTable\").querySelectorAll(\"[data-reject]\").forEach(b=>b.onclick=()=>reviewTeacher(b.dataset.reject,\"REJECT\"));\n}\nasync function reviewTeacher(id,action){\n  const reason=action===\"REJECT\"?prompt(\"Alasan penolakan (opsional):\")||\"\": \"\";\n  if(action===\"REJECT\"&&!confirm(\"Tolak pendaftaran guru ini?\")) return;\n  if(action===\"APPROVE\"&&!confirm(\"Setujui pendaftaran guru ini?\")) return;\n  await api(\"/admin/teachers/approval\",{method:\"POST\",body:JSON.stringify({teacher_id:Number(id),action,rejection_reason:reason})});\n  alert(action===\"APPROVE\"?\"Pendaftaran disetujui.\":\"Pendaftaran ditolak.\"); loadPending();\n}\nasync function loadMonitoring(){\n  const d=todaySchoolDate();\n  setPage(\"monitoring\",`<div class=\"welcome\"><div><h1>Monitoring Presensi</h1><p>Pemantauan kedatangan dan kepulangan guru.</p></div><div>${dateInput(\"monitorDate\",d)} <button class=\"btn-primary\" id=\"runMonitoring\">Tampilkan</button></div></div><div class=\"panel\"><div class=\"panel-header\"><h3>Presensi Harian</h3><small id=\"monitorMeta\"></small></div><div id=\"monitorTable\"></div></div>`);\n  $(\"#runMonitoring\").onclick=renderMonitoring; await renderMonitoring();\n}\nfunction addDays(ymd,n){const [y,m,d]=ymd.split(\"-\").map(Number);return new Date(Date.UTC(y,m-1,d+n)).toISOString().slice(0,10);}\nfunction analysisRange(mode){\n  const today=todaySchoolDate(),to=addDays(today,-1);\n  const from=mode===\"month\"?today.slice(0,8)+\"01\":addDays(today,-Number(mode));\n  return {from,to};\n}\nfunction classifyDatang(s){\n  s=String(s||\"\").toUpperCase();\n  if(s===\"TIDAK DIJADWALKAN\") return null;\n  if(s===\"HADIR\") return \"hadir\";\n  if(s===\"TERLAMBAT\") return \"terlambat\";\n  if(s===\"TIDAK ABSEN DATANG\") return \"alpa\";\n  if(/^(SAKIT|IZIN|CUTI)/.test(s)) return \"izin\";\n  return \"lainnya\";\n}\nfunction pctPill(p){\n  if(p===null) return \"-\";\n  const c=p>=90?[\"#dcfce7\",\"#166534\"]:p>=75?[\"#fef9c3\",\"#854d0e\"]:[\"#ffedd5\",\"#9a3412\"];\n  return `<span style=\"display:inline-block;padding:5px 9px;border-radius:20px;background:${c[0]};color:${c[1]};font-size:11px;font-weight:700\">${p}%</span>`;\n}\nasync function loadAnalysis(){\n  const box=$(\"#analysisBody\"); if(!box) return;\n  const {from,to}=analysisRange($(\"#analysisRange\").value);\n  window.lastAnalysisRange={from,to};\n  if(from>to){box.innerHTML=\"Belum ada hari yang selesai pada periode ini.\";return;}\n  box.innerHTML=\"Memuat analisis...\";\n  const r=await api(`/admin/reports/attendance?from=${from}&to=${to}`);\n  const empty=()=>({hadir:0,terlambat:0,izin:0,alpa:0,lainnya:0});\n  const T=empty(),byTeacher=new Map(),byDate=new Map();\n  for(const x of (r.data||[])){\n    const k=classifyDatang(x.status_datang); if(!k) continue;\n    T[k]++;\n    if(!byTeacher.has(x.teacher_id)) byTeacher.set(x.teacher_id,{name:x.teacher_name,...empty()});\n    byTeacher.get(x.teacher_id)[k]++;\n    if(!byDate.has(x.date)) byDate.set(x.date,empty());\n    byDate.get(x.date)[k]++;\n  }\n  if(!byDate.size){box.innerHTML=\"Tidak ada hari kerja pada periode ini (hari libur atau bukan hari kerja).\";return;}\n  const rate=o=>{const den=o.hadir+o.terlambat+o.alpa+o.lainnya;return den?Math.round((o.hadir+o.terlambat)/den*100):null;};\n  const card=(label,val,color,sub)=>`<div style=\"border:1px solid #e2e8f0;border-radius:12px;padding:14px\"><div style=\"font-size:11px;color:#64748b;font-weight:700\">${label}</div><div style=\"font-size:26px;font-weight:800;color:${color};margin:4px 0\">${val}</div><div style=\"font-size:11px;color:#94a3b8\">${sub}</div></div>`;\n  const overall=rate(T);\n  const cards=`<div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:18px\">`+\n    card(\"TINGKAT KEHADIRAN\",overall===null?\"-\":overall+\"%\",\"#0f766e\",\"Hadir + terlambat\")+\n    card(\"HADIR TEPAT WAKTU\",T.hadir,\"#166534\",\"kali presensi datang\")+\n    card(\"TERLAMBAT\",T.terlambat,\"#c2410c\",\"kali\")+\n    card(\"IZIN / SAKIT / CUTI\",T.izin,\"#1d4ed8\",\"tidak dihitung tidak hadir\")+\n    card(\"TIDAK ABSEN\",T.alpa,\"#b91c1c\",\"tanpa keterangan\")+`</div>`;\n  // Tren harian\n  const days=[...byDate.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([d,o])=>({d,p:rate(o)}));\n  const bars=days.map(x=>{\n    const col=x.p===null?\"#cbd5e1\":x.p>=90?\"#14b8a6\":x.p>=75?\"#eab308\":\"#f97316\";\n    return `<div title=\"${fmtDate(x.d)}: ${x.p===null?\"-\":x.p+\"%\"}\" style=\"flex:1;min-width:14px;display:flex;flex-direction:column;align-items:center;gap:4px\"><div style=\"height:110px;width:100%;display:flex;align-items:flex-end\"><div style=\"width:100%;height:${x.p===null?4:Math.max(x.p,3)}%;background:${col};border-radius:4px 4px 0 0\"></div></div><small style=\"font-size:9px;color:#64748b\">${x.d.slice(8)}/${x.d.slice(5,7)}</small></div>`;\n  }).join(\"\");\n  const trend=`<h4 style=\"margin:0 0 8px;font-size:13px;color:#1e293b\">Tren Kehadiran Harian</h4><div style=\"overflow-x:auto;margin-bottom:18px\"><div style=\"display:flex;gap:4px;min-width:${days.length*22}px\">${bars}</div></div>`;\n  // Analisis ringkas\n  const arr=[...byTeacher.values()];\n  const ranked=days.filter(x=>x.p!==null).sort((a,b)=>a.p-b.p);\n  const top=(key)=>arr.filter(t=>t[key]>0).sort((a,b)=>b[key]-a[key]).slice(0,3).map(t=>`${esc(t.name)} (${t[key]}x)`).join(\", \");\n  const li=[];\n  if(ranked.length) li.push(`Kehadiran tertinggi: <b>${fmtDate(ranked[ranked.length-1].d)}</b> (${ranked[ranked.length-1].p}%). Terendah: <b>${fmtDate(ranked[0].d)}</b> (${ranked[0].p}%).`);\n  if(top(\"terlambat\")) li.push(`Paling sering terlambat: ${top(\"terlambat\")}.`);\n  if(top(\"alpa\")) li.push(`Paling sering tidak absen: ${top(\"alpa\")}.`);\n  const low=arr.filter(t=>rate(t)!==null&&rate(t)<75).length;\n  if(low) li.push(`<b>${low} guru</b> memiliki tingkat kehadiran di bawah 75%.`);\n  if(T.lainnya) li.push(`${T.lainnya} presensi berstatus lain (perlu dicek di Laporan Presensi).`);\n  const insight=`<h4 style=\"margin:0 0 8px;font-size:13px;color:#1e293b\">Analisis</h4><ul style=\"margin:0 0 18px;padding-left:18px;line-height:1.8;color:#475569\">${li.length?li.map(x=>`<li>${x}</li>`).join(\"\"):\"<li>Tidak ada temuan khusus pada periode ini.</li>\"}</ul>`;\n  // Rekap per guru\n  const rows=arr.sort((a,b)=>(rate(a)??101)-(rate(b)??101)||a.name.localeCompare(b.name)).map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.name)}</td><td>${t.hadir}</td><td>${t.terlambat}</td><td>${t.izin}</td><td>${t.alpa}</td><td>${pctPill(rate(t))}</td></tr>`).join(\"\");\n  const recap=`<h4 style=\"margin:0 0 8px;font-size:13px;color:#1e293b\">Rekap per Guru</h4>`+table([\"No\",\"Nama Guru\",\"Hadir\",\"Terlambat\",\"Izin/Sakit/Cuti\",\"Tidak Absen\",\"Kehadiran\"],rows);\n  box.innerHTML=`<p style=\"font-size:12px;color:#64748b;margin:0 0 14px\">Periode ${fmtDate(from)} – ${fmtDate(to)} · ${byDate.size} hari kerja · hari ini belum dihitung · berdasarkan presensi datang</p>`+cards+trend+insight+recap;\n}\nfunction printAnalysis(){\n  const body=$(\"#analysisBody\");\n  if(!body||!body.querySelector(\"table\")){alert(\"Data analisis belum tersedia untuk dicetak.\");return;}\n  const r=window.lastAnalysisRange||{from:\"\",to:\"\"};\n  const when=new Date().toLocaleString(\"id-ID\",{timeZone:schoolTimezone,dateStyle:\"long\",timeStyle:\"short\"});\n  $(\"#printHeader\").innerHTML=`<h2 style=\"margin:0 0 2px;font-size:18px;color:#0f172a\">${esc(currentSettings?.school_name||\"SIAP GURU\")}</h2><p style=\"margin:0 0 14px;font-size:11px;color:#64748b\">Dicetak: ${esc(when)}</p>`;\n  const oldTitle=document.title;\n  document.title=\"Rekap_Analisis_Presensi_\"+r.from+\"_\"+r.to;\n  document.body.classList.add(\"print-analysis\");\n  const done=()=>{document.body.classList.remove(\"print-analysis\");document.title=oldTitle;};\n  window.addEventListener(\"afterprint\",done,{once:true});\n  window.print();\n}\ndocument.addEventListener(\"click\",e=>{if(e.target&&e.target.id===\"printAnalysis\") printAnalysis();});\ndocument.addEventListener(\"change\",e=>{if(e.target&&e.target.id===\"analysisRange\") loadAnalysis().catch(err=>{$(\"#analysisBody\").textContent=err.message||\"Gagal memuat analisis.\";});});\nasync function renderMonitoring(){\n  const r=await api(\"/admin/attendance/monitoring?date=\"+encodeURIComponent($(\"#monitorDate\").value));\n  $(\"#monitorMeta\").textContent=`${r.total_teachers} guru · ${r.is_holiday?\"Hari libur\":r.is_work_day?\"Hari kerja\":\"Bukan hari kerja\"}`;\n  const rows=(r.data||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.teacher_name)}</td><td>${statusPill(x.status_datang)}</td><td>${fmtTime(x.waktu_datang)}</td><td>${statusPill(x.status_pulang)}</td><td>${fmtTime(x.waktu_pulang)}</td></tr>`).join(\"\");\n  $(\"#monitorTable\").innerHTML=`<div style=\"display:flex;gap:18px;flex-wrap:wrap;margin-bottom:15px;font-size:13px\"><b>Hadir: ${r.total_hadir}</b><b>Belum datang: ${r.total_belum_datang}</b><b>Belum pulang: ${r.total_belum_pulang}</b></div>`+table([\"No\",\"Nama Guru\",\"Status Datang\",\"Waktu\",\"Status Pulang\",\"Waktu\"],rows);\n}\nasync function loadReports(){\n  const d=todaySchoolDate();\n  setPage(\"laporan\",`<div class=\"welcome\"><div><h1>Laporan Presensi</h1><p>Rekapitulasi presensi guru. Maksimal rentang 31 hari.</p></div><div>${dateInput(\"reportFrom\",d)} ${dateInput(\"reportTo\",d)} <button class=\"btn-primary\" id=\"runReport\">Tampilkan</button></div></div><div class=\"panel\"><div class=\"panel-header\"><h3>Hasil Laporan</h3><button class=\"btn-primary\" id=\"exportReport\">Unduh CSV</button></div><div id=\"reportMeta\"></div><div id=\"reportTable\"></div></div>`);\n  $(\"#runReport\").onclick=renderReport; $(\"#exportReport\").onclick=exportReport; await renderReport();\n}\nlet reportRows=[];\nasync function renderReport(){\n  const from=$(\"#reportFrom\").value,to=$(\"#reportTo\").value;\n  const r=await api(`/admin/reports/attendance?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);\n  reportRows=r.data||[]; $(\"#reportMeta\").innerHTML=`<p style=\"font-size:12px;color:#64748b\">${r.total_teachers} guru · ${r.total_days} hari · ${r.total_records} baris</p>`;\n  const rows=reportRows.map((x,i)=>`<tr><td>${i+1}</td><td>${fmtDate(x.date)}</td><td>${esc(x.teacher_name)}</td><td>${statusPill(x.status_datang)}</td><td>${fmtTime(x.waktu_datang)}</td><td>${statusPill(x.status_pulang)}</td><td>${fmtTime(x.waktu_pulang)}</td></tr>`).join(\"\");\n  $(\"#reportTable\").innerHTML=table([\"No\",\"Tanggal\",\"Nama Guru\",\"Datang\",\"Jam\",\"Pulang\",\"Jam\"],rows);\n}\nfunction exportReport(){\n  if(!reportRows.length){alert(\"Tidak ada data untuk diunduh.\");return;}\n  const cols=[\"date\",\"teacher_name\",\"status_datang\",\"waktu_datang\",\"status_pulang\",\"waktu_pulang\"];\n  const csv=[[\"Tanggal\",\"Nama Guru\",\"Status Datang\",\"Waktu Datang\",\"Status Pulang\",\"Waktu Pulang\"],...reportRows.map(r=>cols.map(k=>r[k]??\"\"))].map(row=>row.map(v=>`\"${String(v).replace(/\"/g,'\"\"')}\"`).join(\",\")).join(\"\\r\\n\");\n  const a=document.createElement(\"a\"),url=URL.createObjectURL(new Blob([\"\\ufeff\"+csv],{type:\"text/csv;charset=utf-8\"}));\n  a.href=url;a.download=\"Laporan_Presensi_SIAP_GURU.csv\";a.click();URL.revokeObjectURL(url);\n}\nasync function loadLeaves(){\n  setPage(\"izin\",`<div class=\"welcome\"><div><h1>Izin & Cuti</h1><p>Daftar pengajuan izin dan cuti guru.</p></div><select id=\"leaveStatus\" style=\"padding:10px;border:1px solid #dbe3e8;border-radius:9px\"><option>ALL</option><option>PENDING</option><option>APPROVED</option><option>REJECTED</option></select></div><div class=\"panel\"><div class=\"panel-header\"><h3>Pengajuan Guru</h3><small id=\"leaveCount\"></small></div><div id=\"leaveTable\"></div></div>`);\n  $(\"#leaveStatus\").onchange=renderLeaves; await renderLeaves();\n}\nasync function renderLeaves(){\n  const r=await api(\"/admin/leave-requests?status=\"+$(\"#leaveStatus\").value);$(\"#leaveCount\").textContent=`${r.total||0} pengajuan`;\n  const rows=(r.data||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.full_name)}</td><td>${esc(x.leave_type)}</td><td>${x.approval_status===\"PENDING\"&&x.leave_type!==\"SAKIT\"?\"Belum ditetapkan\":`${fmtDate(x.start_date)} – ${fmtDate(x.end_date)}`}</td><td>${esc(x.reason)}${x.admin_note?`<div style=\"font-size:11px;color:#64748b\">${esc(x.admin_note)}</div>`:\"\"}</td><td>${x.attachment_url&&String(x.attachment_url).startsWith(\"tg:\")?`<button class=\"btn-primary\" data-leave-file=\"${x.id}\">📎 Lihat Surat</button>`:\"Tidak ada\"}</td><td>${statusPill(x.approval_status)}</td><td>${x.approval_status===\"APPROVED\"&&!x.reviewed_by?`<button class=\"btn-danger\" data-leave-reject=\"${x.id}\">Tolak</button>`:x.approval_status===\"PENDING\"?`<button class=\"btn-primary\" data-leave-approve=\"${x.id}\" data-type=\"${esc(x.leave_type)}\" data-start=\"${esc(x.start_date)}\" data-end=\"${esc(x.end_date)}\">Setujui</button> <button class=\"btn-danger\" data-leave-reject=\"${x.id}\">Tolak</button>`:\"-\"}</td></tr>`).join(\"\");\n  $(\"#leaveTable\").innerHTML=table([\"No\",\"Nama\",\"Jenis\",\"Periode\",\"Alasan\",\"Lampiran\",\"Status\",\"Tindakan\"],rows,\"Belum ada pengajuan.\");\n  $(\"#leaveTable\").querySelectorAll(\"[data-leave-file]\").forEach(b=>b.onclick=()=>openLeaveFile(b.dataset.leaveFile));\n  $(\"#leaveTable\").querySelectorAll(\"[data-leave-approve]\").forEach(b=>b.onclick=()=>reviewLeave(b.dataset.leaveApprove,\"APPROVE\",{type:b.dataset.type,start:b.dataset.start,end:b.dataset.end}));\n  $(\"#leaveTable\").querySelectorAll(\"[data-leave-reject]\").forEach(b=>b.onclick=()=>reviewLeave(b.dataset.leaveReject,\"REJECT\"));\n}\nasync function openLeaveFile(id){\n  const w=window.open(\"\",\"_blank\");\n  try{\n    const res=await fetch(API_BASE+\"/admin/leave-requests/attachment?id=\"+encodeURIComponent(id),{headers:{Authorization:\"Bearer \"+token()}});\n    if(!res.ok)throw new Error(\"gagal\");\n    const blob=await res.blob();\n    const u=URL.createObjectURL(blob);\n    if(w)w.location=u;else window.open(u,\"_blank\");\n  }catch(e){if(w)w.close();alert(\"Lampiran tidak dapat dibuka.\");}\n}\nasync function reviewLeave(id,action,meta={}){\n  if(!confirm(action===\"APPROVE\"?\"Setujui pengajuan ini?\":\"Tolak pengajuan ini?\"))return;\n  const payload={request_id:Number(id),action};\n  if(action===\"APPROVE\"&&meta.type&&meta.type!==\"SAKIT\"){\n    const today=new Intl.DateTimeFormat(\"en-CA\",{timeZone:schoolTimezone}).format(new Date());\n    const s=(prompt(\"Tanggal MULAI \"+meta.type+\" (format YYYY-MM-DD):\",today)||\"\").trim();\n    if(!s)return;\n    const e=(prompt(\"Tanggal SELESAI \"+meta.type+\" (format YYYY-MM-DD):\",s)||\"\").trim();\n    if(!e)return;\n    payload.start_date=s;payload.end_date=e;\n  }\n  payload.admin_note=prompt(\"Catatan admin (opsional):\")||\"\";\n  try{\n    await api(\"/admin/leave-requests/review\",{method:\"POST\",body:JSON.stringify(payload)});\n    alert(\"Pengajuan berhasil diproses.\");\n  }catch(err){alert(err.message||\"Gagal memproses pengajuan.\");}\n  renderLeaves();\n}\nasync function loadSettings(){\n  setPage(\"pengaturan\",`<div class=\"welcome\"><div><h1>Pengaturan Sistem</h1><p>Konfigurasi presensi Nama Sekolah.</p></div></div><div class=\"panel\"><div id=\"settingsForm\">Memuat pengaturan...</div></div><div class=\"panel\" style=\"margin-top:18px\"><div class=\"panel-header\"><h3>Hari Libur</h3><small>Kelola kalender sekolah</small></div><div style=\"display:flex;gap:10px;flex-wrap:wrap;margin-bottom:15px\">${dateInput(\"holidayDate\",todaySchoolDate())}<input id=\"holidayDesc\" placeholder=\"Keterangan hari libur\" style=\"padding:10px;border:1px solid #dbe3e8;border-radius:9px;flex:1;min-width:180px\"><button class=\"btn-primary\" id=\"addHoliday\">Tambah</button></div><div id=\"holidayTable\"></div></div>`);\n  const r=await api(\"/admin/settings\");currentSettings=r.data;schoolTimezone=currentSettings.timezone||\"Asia/Makassar\";applySchoolIdentity(currentSettings.school_name);renderSettingsForm(currentSettings);\n  $(\"#settingsForm\").querySelector(\"form\").onsubmit=saveSettings;\n  $(\"#addHoliday\").onclick=addHoliday; await loadHolidays();\n}\nfunction renderSettingsForm(s){\n  const days=[\"Minggu\",\"Senin\",\"Selasa\",\"Rabu\",\"Kamis\",\"Jumat\",\"Sabtu\"],active=String(s.work_days||\"\").split(\",\").map(Number);\n  $(\"#settingsForm\").innerHTML=`<h3 style=\"font-size:14px\">Informasi Sekolah & Presensi</h3><form class=\"settings-grid\">\n    ${field(\"Nama Sekolah\",\"school_name\",s.school_name)} ${field(\"NPSN\",\"npsn\",s.npsn)}\n    ${tzField(s.timezone)} ${field(\"Jam Mulai Presensi\",\"arrival_time\",s.arrival_time,\"time\")}\n    ${field(\"Jam Pulang\",\"departure_time\",s.departure_time,\"time\")} ${field(\"Radius GPS (meter)\",\"gps_radius\",s.gps_radius,\"number\")}\n    ${field(\"Latitude Sekolah\",\"gps_latitude\",s.gps_latitude,\"number\")} ${field(\"Longitude Sekolah\",\"gps_longitude\",s.gps_longitude,\"number\")}\n    <div style=\"grid-column:1/-1\"><b style=\"font-size:12px\">Hari Kerja</b><div style=\"display:flex;gap:12px;flex-wrap:wrap;margin-top:10px\">${days.map((d,i)=>`<label style=\"font-size:12px\"><input type=\"checkbox\" name=\"work_days\" value=\"${i}\" ${active.includes(i)?\"checked\":\"\"}> ${d}</label>`).join(\"\")}</div></div>\n    <div style=\"grid-column:1/-1\"><button class=\"btn-primary\" type=\"submit\">Simpan Pengaturan</button> <span id=\"settingsMessage\" style=\"font-size:12px;color:#64748b\"></span></div></form>`;\n}\nfunction tzField(value){\n  const opts=[[\"Asia/Jakarta\",\"WIB (Asia/Jakarta)\"],[\"Asia/Makassar\",\"WITA (Asia/Makassar)\"],[\"Asia/Jayapura\",\"WIT (Asia/Jayapura)\"]];\n  if(value&&!opts.some(o=>o[0]===value))opts.push([value,value]);\n  return `<label style=\"display:flex;flex-direction:column;gap:6px;font-size:12px;color:#475569\">Zona Waktu<select name=\"timezone\" style=\"padding:10px;border:1px solid #dbe3e8;border-radius:9px;width:100%;background:#fff\">${opts.map(o=>`<option value=\"${esc(o[0])}\" ${o[0]===(value||\"Asia/Makassar\")?\"selected\":\"\"}>${esc(o[1])}</option>`).join(\"\")}</select></label>`;\n}\nfunction field(label,name,value,type=\"text\"){return `<label style=\"display:flex;flex-direction:column;gap:6px;font-size:12px;color:#475569\">${label}<input name=\"${name}\" type=\"${type}\" value=\"${esc(value)}\" style=\"padding:10px;border:1px solid #dbe3e8;border-radius:9px;width:100%\" ${type===\"number\"?'step=\"any\"':\"\"}></label>`;}\nasync function saveSettings(e){\n  e.preventDefault();const f=e.currentTarget,fd=new FormData(f),body={};\n  [\"school_name\",\"npsn\",\"timezone\",\"arrival_time\",\"departure_time\",\"gps_latitude\",\"gps_longitude\",\"gps_radius\"].forEach(k=>body[k]=fd.get(k));\n  body.gps_latitude=body.gps_latitude===\"\"?null:Number(body.gps_latitude);body.gps_longitude=body.gps_longitude===\"\"?null:Number(body.gps_longitude);body.gps_radius=Number(body.gps_radius);\n  body.work_days=fd.getAll(\"work_days\").map(Number);\n  try{\n    const result=await api(\"/admin/settings\",{method:\"PATCH\",body:JSON.stringify(body)});\n    currentSettings=result.data||body;\n    schoolTimezone=currentSettings.timezone||schoolTimezone;\n    applySchoolIdentity(currentSettings.school_name);\n    $(\"#settingsMessage\").textContent=\"Pengaturan berhasil disimpan.\";\n  } catch(e){alert(e.message);}\n}\nasync function loadHolidays(){\n  const r=await api(\"/admin/holidays\");const rows=(r.data||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${fmtDate(x.holiday_date)}</td><td>${esc(x.description)}</td><td><button class=\"btn-danger\" data-holiday=\"${esc(x.holiday_date)}\">Hapus</button></td></tr>`).join(\"\");\n  $(\"#holidayTable\").innerHTML=table([\"No\",\"Tanggal\",\"Keterangan\",\"Tindakan\"],rows,\"Belum ada hari libur.\");\n  $(\"#holidayTable\").querySelectorAll(\"[data-holiday]\").forEach(b=>b.onclick=()=>deleteHoliday(b.dataset.holiday));\n}\nasync function addHoliday(){\n  const date=$(\"#holidayDate\").value,description=$(\"#holidayDesc\").value.trim();if(!date||!description){alert(\"Tanggal dan keterangan wajib diisi.\");return;}\n  try{await api(\"/admin/holidays\",{method:\"POST\",body:JSON.stringify({holiday_date:date,description})});$(\"#holidayDesc\").value=\"\";await loadHolidays();}\n  catch(e){alert(e.message);}\n}\nasync function deleteHoliday(date){\n  if(!confirm(\"Hapus hari libur \"+date+\"?\"))return;\n  try{await api(\"/admin/holidays\",{method:\"DELETE\",body:JSON.stringify({holiday_date:date})});await loadHolidays();}\n  catch(e){alert(e.message);}\n}\n\ndocument.querySelectorAll(\".nav-item\").forEach(b=>b.addEventListener(\"click\",()=>showPage(b.dataset.page)));\ndocument.querySelectorAll(\".quick\").forEach(b=>b.addEventListener(\"click\",()=>showPage(b.dataset.target)));\n$(\"#toggleMenu\").addEventListener(\"click\",()=>$(\"#sidebar\").classList.toggle(\"open\"));\nverifyAdminSession();\n\n</script>\n</body>\n</html>\n";

const PLACEHOLDER = '"__ISI_URL_WORKER__"';

const HALAMAN_ERROR = `<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Konfigurasi belum lengkap</title></head><body style="font-family:system-ui,sans-serif;max-width:520px;margin:12vh auto;padding:24px;border:1px solid #fecaca;background:#fef2f2;border-radius:12px;color:#7f1d1d"><h2 style="margin:0 0 8px">Konfigurasi belum lengkap</h2><p style="margin:0;line-height:1.5">Variabel <b>API_URL</b> pada Worker dashboard ini belum diisi dengan benar. Isi dengan alamat Worker API sekolah (diawali https://, tanpa garis miring di akhir), lalu klik Deploy.</p></body></html>`;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (!["/", "/admin.html", "/index.html"].includes(url.pathname)) {
      return new Response("Halaman tidak ditemukan", { status: 404 });
    }
    const headers = { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" };
    const api = String(env.API_URL || "").trim();
    if (!/^https:\/\/[^\s/]+$/.test(api)) {
      return new Response(HALAMAN_ERROR, { status: 500, headers });
    }
    return new Response(ADMIN_HTML.replace(PLACEHOLDER, () => JSON.stringify(api)), { headers });
  }
};
